let lang="ar",skill="all",serviceCat="all",creatorLimit=3,workExpanded=false,zoom=1,slide=0;
function t(k){return translations[lang][k]||k}
function setLanguage(v){lang=v;document.documentElement.lang=v;document.documentElement.dir=v==="ar"?"rtl":"ltr";document.body.classList.toggle("en",v==="en");$$("[data-t]").forEach(el=>{const k=el.dataset.t;if(translations[v][k])el.innerHTML=translations[v][k]});$$("[data-ph]").forEach(el=>el.placeholder=translations[v][el.dataset.ph]||"");$("#lang").textContent=v==="ar"?"EN":"عربي";applyAuthUser(currentAuthUser);$("#creatorSearch").placeholder=t("creatorSearchPlaceholder");$("#serviceSearch").placeholder=t("serviceSearchPlaceholder");renderCreators();renderServices();if(activeProfileId)renderProfilePage(activeProfileId);else if(activeMemberUsername)renderMemberProfile(activeMemberUsername)}
function verificationBadge(c){if(!c.verified)return "";const label=lang==="ar"?"حساب موثّق رسمياً من LENSORA":"Officially verified LENSORA account";return '<button type="button" class="verified-badge" data-verified-id="'+c.id+'" aria-label="'+label+'" title="'+label+'">✓</button>'}
function showVerification(id){const c=creators.find(x=>x.id===Number(id));if(!c||!c.verified)return;const message=lang==="ar"?"هذا الحساب موثّق رسمياً من LENSORA بعد مراجعة الإدارة والتحقق من بيانات صاحبه.":"This account is officially verified by LENSORA after administrative review and identity checks.";$("#modalContent").innerHTML='<div class="eyebrow">LENSORA</div><h2>'+(lang==="ar"?"توثيق الحساب":"Account verification")+'</h2><div class="verification-copy"><span class="verified-badge" aria-hidden="true">✓</span><p style="margin:0">'+message+'</p></div>';$("#modal").classList.add("open")}
function bindVerifiedBadges(){$$("[data-verified-id]").forEach(b=>b.onclick=()=>showVerification(b.dataset.verifiedId))}
function creatorCard(c,index=0){const name=lang==="ar"?c.ar:c.en,role=lang==="ar"?c.roleAr:c.roleEn;return '<article class="creator" style="--card-index:'+Math.min(index,8)+'"><img class="avatar" src="'+c.img+'" alt="'+name+'"><div><h3>'+name+' '+verificationBadge(c)+' <span class="creator-role">'+c.user+'</span></h3><div class="creator-role">'+role+'</div><div class="creator-meta">'+c.city+' · '+(lang==="ar"?"الأردن":"Jordan")+' · '+c.works+' '+t("works")+' · '+c.exp+' '+t("years")+' · ★ '+c.rating+'</div><p class="creator-bio">'+(lang==="ar"?c.bioAr:c.bioEn)+'</p><div class="tags">'+(lang==="ar"?c.skillsAr:c.skillsEn).split(" · ").map(x=>'<span class="tag">'+x+'</span>').join("")+'</div></div><div class="creator-actions"><button class="text-btn profile-preview-btn" data-preview-profile="'+c.id+'"><span class="profile-preview-icon" aria-hidden="true">◉</span><span>'+(lang==="ar"?"معاينة":"Preview")+'</span></button><button class="text-btn profile-open-btn" data-open-profile="'+c.id+'"><span class="profile-open-icon" aria-hidden="true">↗</span><span>'+t("viewProfile")+'</span></button></div></article>'}
function renderCreators(){let q=$("#creatorSearch").value.trim().toLowerCase(),city=$("#cityFilter").value,exp=$("#experienceFilter").value;let arr=creators.filter(c=>{let hay=[c.ar,c.en,c.user,c.roleAr,c.roleEn,c.city,c.skillsAr,c.skillsEn].join(" ").toLowerCase();return(!q||hay.includes(q))&&(skill==="all"||c.skills.includes(skill))&&(!city||c.city===city)&&(!exp||String(c.exp===1?1:c.exp<=2?2:c.exp<=5?3:c.exp<=10?4:5)===exp)});let shown=arr.slice(0,creatorLimit);$("#creatorResults").innerHTML=shown.map((c,i)=>creatorCard(c,i)).join("");$("#noCreators").hidden=arr.length>0;$("#moreCreators").hidden=creatorLimit>=arr.length;$("#moreCreators").textContent=lang==="ar"?"عرض المزيد ("+Math.max(0,arr.length-creatorLimit)+")": "Show more ("+Math.max(0,arr.length-creatorLimit)+")";bindProfiles()}
function bindProfiles(){$$("[data-open-profile]").forEach(b=>b.onclick=()=>openProfile(Number(b.dataset.openProfile)));$$("[data-preview-profile]").forEach(b=>b.onclick=()=>previewProfile(Number(b.dataset.previewProfile)));bindVerifiedBadges()}
function previewProfile(id){const c=creators.find(x=>x.id===id);if(!c)return;const name=lang==="ar"?c.ar:c.en;const bio=lang==="ar"?c.bioAr:c.bioEn;const role=lang==="ar"?c.roleAr:c.roleEn;const skills=lang==="ar"?c.skillsAr:c.skillsEn;$("#modalContent").innerHTML='<div class="profile-preview-head"><img src="'+c.img+'" alt="'+name+'"><div><div class="eyebrow">'+(lang==="ar"?"نبذة سريعة عن المبدع":"Creator quick preview")+'</div><h2>'+name+' '+verificationBadge(c)+'</h2><div class="creator-role">'+role+' · '+c.user+'</div><small class="creator-meta">'+c.city+' · '+(lang==="ar"?"الأردن":"Jordan")+'</small></div></div><p class="profile-preview-bio">'+bio+'</p><div class="tags">'+skills.split(" · ").map(x=>'<span class="tag">'+x+'</span>').join("")+'</div><div class="profile-preview-stats"><span>★ '+c.rating+'</span><span>'+c.works+' '+(lang==="ar"?"عملاً":"works")+'</span><span>'+c.exp+' '+(lang==="ar"?"سنوات خبرة":"years experience")+'</span></div><div class="profile-preview-actions"><button class="btn" data-preview-visit="'+c.id+'">'+(lang==="ar"?"زيارة الملف الشخصي":"Visit profile")+' ↗</button><button class="text-btn" id="previewClose">'+(lang==="ar"?"إغلاق":"Close")+'</button></div><p class="notice">'+(lang==="ar"?"هذه نبذة تجريبية مختصرة. يمكنك زيارة الملف للاطلاع على تفاصيل أكثر والأعمال المعروضة.":"This is a short demo preview. Visit the profile for more details and work samples.")+'</p>';$("#modal").classList.add("open");$$("[data-verified-id]").forEach(b=>b.onclick=()=>showVerification(b.dataset.verifiedId));$$("[data-preview-visit]").forEach(b=>b.onclick=()=>{$("#modal").classList.remove("open");openProfile(Number(b.dataset.previewVisit))});$("#previewClose").onclick=()=>$("#modal").classList.remove("open")}

let activeProfileId=null,activeMemberUsername=null;
function profileUrl(c){return "/@"+c.user.replace(/^@/,"")}
function renderProfilePage(id){
const c=creators.find(x=>x.id===Number(id));if(!c)return;activeProfileId=c.id;document.body.classList.add("profile-route");const brandLink=document.querySelector(".topbar .brand");if(brandLink)brandLink.href="/";
const ar=lang==="ar",name=ar?c.ar:c.en,role=ar?c.roleAr:c.roleEn,bio=ar?c.bioAr:c.bioEn,skills=ar?c.skillsAr:c.skillsEn,items=portfolios[c.id-1]||[],idx=creators.findIndex(x=>x.id===c.id),prev=creators[(idx+creators.length-1)%creators.length],next=creators[(idx+1)%creators.length];
$("#profilePage").innerHTML='<div class="profile-shell"><div class="profile-topline"><a class="profile-back-link" href="/" id="profileBack">← '+(ar?"العودة إلى دليل المبدعين":"Back to creator directory")+'</a><span class="eyebrow">LENSORA / CREATOR '+String(c.id).padStart(2,"0")+'</span></div>'+
'<div class="profile-cover" style="background-image:url('+JSON.stringify(c.cover||((items[0]&&items[0].image)||c.img))+')"><div class="profile-cover-caption"><span class="eyebrow">CREATIVE PORTFOLIO</span><h1>'+name+' '+verificationBadge(c)+'</h1><p>'+role+' · '+c.user+'</p></div></div>'+
'<div class="profile-main"><aside class="profile-side"><img class="profile-large-avatar" src="'+c.img+'" alt="'+name+'"><h2>'+name+' '+verificationBadge(c)+'</h2><p class="creator-role">'+role+'</p><div class="profile-location">⌖ '+c.city+' · '+(ar?"الأردن":"Jordan")+'</div><div class="profile-stats"><span><b>'+items.length+'</b><small>'+(ar?"مشاريع":"Projects")+'</small></span><span><b>'+c.rating+'</b><small>'+(ar?"التقييم":"Rating")+'</small></span><span><b>'+c.exp+'</b><small>'+(ar?"سنوات خبرة":"Years")+'</small></span></div><div class="profile-side-note">'+(ar?"ملف تجريبي ضمن معرض LENSORA لاستعراض شكل الملفات الشخصية وتصفح الأعمال.":"Demo profile in the LENSORA showcase to explore creator pages and portfolios.")+'</div></aside>'+
'<div class="profile-content"><section class="profile-section"><span class="eyebrow">'+(ar?"نبذة تعريفية":"ABOUT")+'</span><h2>'+(ar?"نبذة عن المبدع":"About")+'</h2><p>'+bio+'</p></section><section class="profile-section"><span class="eyebrow">'+(ar?"المهارات والتخصصات":"SPECIALTIES")+'</span><h2>'+(ar?"المهارات":"Skills")+'</h2><div class="tags">'+skills.split(" · ").map(x=>'<span class="tag">'+x+'</span>').join("")+'</div></section>'+
'<section class="profile-section"><div class="section-head"><div><span class="eyebrow">'+(ar?"معرض الأعمال":"PORTFOLIO")+'</span><h2>'+(ar?"الأعمال والمشاريع":"Works & projects")+'</h2></div><p>'+(ar?"تصفح نماذج من أعمال هذا المبدع، واضغط على أي عمل لعرضه بحجم أكبر.":"Explore this creator’s projects and open any item to view it larger.")+'</p></div><div class="profile-gallery">'+items.map((w,i)=>'<button class="profile-work" data-profile-work="'+i+'"><img loading="lazy" src="'+w.image+'" alt="'+(ar?w.ar:w.en)+'"><div class="profile-work-info"><b>'+(ar?w.ar:w.en)+'</b><small>'+(ar?w.catAr:w.catEn)+'</small><p>'+(ar?w.descAr:w.descEn)+'</p></div></button>').join("")+'</div></section>'+
'<section class="profile-section"><span class="eyebrow">'+(ar?"معلومات مهنية":"PROFESSIONAL DETAILS")+'</span><h2>'+(ar?"الخبرة والموقع":"Experience & location")+'</h2><div class="profile-detail-row"><span>'+(ar?"سنوات الخبرة":"Experience")+'</span><b>'+c.exp+' '+(ar?"سنوات":"years")+'</b></div><div class="profile-detail-row"><span>'+(ar?"الموقع":"Location")+'</span><b>'+c.city+' · '+(ar?"الأردن":"Jordan")+'</b></div><div class="profile-detail-row"><span>'+(ar?"اسم المستخدم":"Username")+'</span><b>'+c.user+'</b></div></section>'+
'<nav class="profile-switch"><a href="'+profileUrl(prev)+'" data-profile-nav="'+prev.id+'">← '+(ar?"الملف السابق":"Previous profile")+'</a><a href="'+profileUrl(next)+'" data-profile-nav="'+next.id+'">'+(ar?"الملف التالي":"Next profile")+' →</a></nav></div></div></div>';
$$("[data-verified-id]").forEach(x=>x.onclick=e=>{e.preventDefault();e.stopPropagation();showVerification(x.dataset.verifiedId)});
$$("[data-profile-work]").forEach(x=>x.onclick=()=>{const w=items[Number(x.dataset.profileWork)];$("#lightboxImage").src=w.image;$("#lightboxTitle").textContent=(ar?w.ar:w.en)+" · "+(ar?w.catAr:w.catEn);zoom=1;$("#lightboxImage").style.transform="scale(1)";$("#lightbox").classList.add("open")});
$$("[data-profile-nav]").forEach(x=>x.onclick=e=>{e.preventDefault();const to=Number(x.dataset.profileNav),target=creators.find(y=>y.id===to);history.pushState({profile:to},"",profileUrl(target));renderProfilePage(to);window.scrollTo(0,0)});
}
function openProfile(id){const c=creators.find(x=>x.id===Number(id));if(!c)return;history.pushState({profile:c.id},"",profileUrl(c));renderProfilePage(c.id);window.scrollTo(0,0)}
function showDirectory(){activeProfileId=null;activeMemberUsername=null;document.body.classList.remove("profile-route");const brandLink=document.querySelector(".topbar .brand");if(brandLink)brandLink.href="#home";$("#profilePage").innerHTML=""}
window.addEventListener("popstate",()=>{let path=location.pathname;try{path=decodeURIComponent(path)}catch(e){}const m=path.match(/^\/@([^/]+)$/);if(m){const c=creators.find(x=>x.user.replace(/^@/,"").toLowerCase()===m[1].toLowerCase());if(c)renderProfilePage(c.id);else renderMemberProfile(m[1])}else showDirectory()});
