  const imageUrl=v=>{const x=str(v,1000);if(!x)return "";try{const u=new URL(x);return u.protocol==="https:"?x:"INVALID"}catch{return "INVALID"}};
  const rawAvatar=str(body.avatarUrl,1000),ownAvatarPrefix="/media/profile-avatars/"+user.id+"/",avatar=rawAvatar.startsWith(ownAvatarPrefix)&&/^\/media\/profile-avatars\/[0-9a-f-]{36}\/[0-9a-f-]{36}\.(?:jpg|png|webp|avif)$/i.test(rawAvatar)?rawAvatar:imageUrl(rawAvatar),cover=imageUrl(body.coverUrl);if(avatar==="INVALID"||cover==="INVALID")return authJson({error:"INVALID_IMAGE_URL"},400);
