async function handleMedia(request,env,url){
 if(!url.pathname.startsWith("/media/"))return null;
 if(request.method!=="GET")return new Response("Method not allowed",{status:405,headers:{allow:"GET"}});
 if(!env?.MEDIA)return new Response("Media unavailable",{status:503});
 let key;try{key=decodeURIComponent(url.pathname.slice(7))}catch{return new Response("Not found",{status:404})}if(!/^(?:portfolio|profile-avatars)\/[0-9a-f-]{36}\/[0-9a-f-]{36}\.(?:jpg|png|webp|avif)$/i.test(key))return new Response("Not found",{status:404});
 const object=await env.MEDIA.get(key);if(!object)return new Response("Not found",{status:404});
 const headers=new Headers();object.writeHttpMetadata(headers);headers.set("etag",object.httpEtag);headers.set("cache-control","public, max-age=31536000, immutable");headers.set("x-content-type-options","nosniff");
 return new Response(object.body,{headers});
}


async function competitionVoterHash(request){
 const raw=[request.headers.get("cf-connecting-ip")||"",request.headers.get("user-agent")||"",request.headers.get("accept-language")||""].join("|");
 const digest=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(raw));
 return Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,"0")).join("");
}

async function handleCompetitions(request,env,url){
 if(!url.pathname.startsWith("/api/competitions"))return null;
 if(!env?.DB)return authJson({error:"DATABASE_UNAVAILABLE"},503);
 const competitionId=url.pathname.startsWith("/api/competitions/demo/")?"portrait-demo-2026":"portrait-nov-2026";
 const path=url.pathname.replace("/api/competitions/demo","/api/competitions");
 const user=await authCurrentUser(request,env);
 const isAdmin=async()=>!!user&&!!(await env.DB.prepare("SELECT 1 AS ok FROM competition_admins WHERE user_id=?").bind(user.id).first());
 const isStaff=async()=>await panelSessionValid(request,env,"staff");
 if(path==="/api/competitions/public"&&request.method==="GET"){
  const voterHash=await competitionVoterHash(request);
  const c=await env.DB.prepare("SELECT id,title,description,entry_fee_jod,prize_jod,max_participants,status,start_at FROM competitions WHERE id=?").bind(competitionId).first();
  if(!c)return authJson({error:"COMPETITION_NOT_FOUND"},404);
  const counts=await env.DB.prepare("SELECT (SELECT COUNT(*) FROM competition_participants WHERE competition_id=?) AS participants,(SELECT COUNT(*) FROM competition_requests WHERE competition_id=? AND status='pending') AS pending").bind(competitionId,competitionId).first();
  const visible=c.status==="active"||c.status==="completed";
  const participants=visible?await env.DB.prepare("SELECT cp.seed,cp.id AS participant_id,cp.submission_image_url,u.username,u.first_name,u.last_name,p.avatar_url FROM competition_participants cp JOIN users u ON u.id=cp.user_id LEFT JOIN profiles p ON p.user_id=u.id WHERE cp.competition_id=? ORDER BY cp.seed").bind(competitionId).all():{results:[]};
  const matches=await env.DB.prepare("SELECT m.id,m.round,m.match_number,m.starts_at,m.ends_at,m.extension_count,m.status,m.winner_id,m.participant_a,m.participant_b,(SELECT v.participant_id FROM competition_votes v WHERE v.match_id=m.id AND v.voter_hash=?) AS my_vote,pa.username AS a_username,pa.first_name AS a_first_name,pa.last_name AS a_last_name,pb.username AS b_username,pb.first_name AS b_first_name,pb.last_name AS b_last_name,COALESCE(NULLIF(ca.submission_image_url,''),(SELECT '/media/'||pw.object_key FROM profile_works pw WHERE pw.user_id=pa.id ORDER BY pw.created_at DESC LIMIT 1),'') AS a_submission_image,COALESCE(NULLIF(cb.submission_image_url,''),(SELECT '/media/'||pw.object_key FROM profile_works pw WHERE pw.user_id=pb.id ORDER BY pw.created_at DESC LIMIT 1),'') AS b_submission_image,apa.avatar_url AS a_avatar_url,apb.avatar_url AS b_avatar_url,(SELECT COUNT(*) FROM competition_votes v WHERE v.match_id=m.id AND v.participant_id=m.participant_a) AS votes_a,(SELECT COUNT(*) FROM competition_votes v WHERE v.match_id=m.id AND v.participant_id=m.participant_b) AS votes_b FROM competition_matches m LEFT JOIN competition_participants ca ON ca.id=m.participant_a LEFT JOIN users pa ON pa.id=ca.user_id LEFT JOIN profiles apa ON apa.user_id=pa.id LEFT JOIN competition_participants cb ON cb.id=m.participant_b LEFT JOIN users pb ON pb.id=cb.user_id LEFT JOIN profiles apb ON apb.user_id=pb.id WHERE m.competition_id=? ORDER BY m.round DESC,m.match_number").bind(voterHash,competitionId).all();
  return authJson({competition:c,counts:{...counts,participants:visible?Number(counts?.participants||0):0},participants:participants.results||[],matches:visible?(matches.results||[]):[],isAdmin:await isAdmin(),isStaff:await isStaff(),user:user?{id:user.id,username:user.username}:null});
 }
 if(path==="/api/competitions/vote"&&request.method==="POST"){
  const origin=request.headers.get("Origin");if(origin!==url.origin||request.headers.get("Sec-Fetch-Site")==="cross-site")return authJson({error:"CROSS_SITE_REQUEST"},403);
  let body;try{body=await request.json()}catch{return authJson({error:"INVALID_JSON"},400)}
  const matchId=String(body?.matchId||""),participantId=String(body?.participantId||"");
  if(!/^[a-f0-9-]{36}$/i.test(matchId)||!(/^[a-f0-9-]{36}$/i.test(participantId)||participantId==="demo-participant-lensora-2026"))return authJson({error:"INVALID_VOTE"},400);
  const competition=await env.DB.prepare("SELECT status FROM competitions WHERE id=?").bind(competitionId).first();
  if(!competition||competition.status!=="active")return authJson({error:"VOTING_CLOSED"},409);
  const match=await env.DB.prepare("SELECT id,participant_a,participant_b,status,starts_at,ends_at FROM competition_matches WHERE id=? AND competition_id=?").bind(matchId,competitionId).first();
  if(!match)return authJson({error:"MATCH_NOT_FOUND"},404);
  const now=Date.now();
  if(match.status!=="active"||(match.starts_at&&Date.parse(match.starts_at)>now)||(match.ends_at&&Date.parse(match.ends_at)<=now))return authJson({error:"VOTING_CLOSED"},409);
  if(participantId!==match.participant_a&&participantId!==match.participant_b)return authJson({error:"INVALID_PARTICIPANT"},400);
  const voterHash=await competitionVoterHash(request);
  const existing=await env.DB.prepare("SELECT participant_id FROM competition_votes WHERE match_id=? AND voter_hash=?").bind(matchId,voterHash).first();
  if(existing)return authJson({error:"ALREADY_VOTED",votedFor:existing.participant_id},409);
  try{await env.DB.prepare("INSERT INTO competition_votes (id,match_id,participant_id,voter_hash,created_at) VALUES (?,?,?,?,?)").bind(authUuid(),matchId,participantId,voterHash,new Date().toISOString()).run();}
  catch(e){const duplicate=await env.DB.prepare("SELECT participant_id FROM competition_votes WHERE match_id=? AND voter_hash=?").bind(matchId,voterHash).first();if(duplicate)return authJson({error:"ALREADY_VOTED",votedFor:duplicate.participant_id},409);throw e;}
  const totals=await env.DB.prepare("SELECT SUM(CASE WHEN participant_id=? THEN 1 ELSE 0 END) AS votes_a,SUM(CASE WHEN participant_id=? THEN 1 ELSE 0 END) AS votes_b FROM competition_votes WHERE match_id=?").bind(match.participant_a,match.participant_b,matchId).first();
  return authJson({ok:true,votesA:Number(totals?.votes_a||0),votesB:Number(totals?.votes_b||0),pointsA:Number(totals?.votes_a||0)*5,pointsB:Number(totals?.votes_b||0)*5,pointsPerVote:5,message:"تم تسجيل صوتك بنجاح. أضيفت 5 نقاط للمشارك."},201);
 }
 if(path==="/api/competitions/requests"&&request.method==="POST"){
  if(!user)return authJson({error:"AUTH_REQUIRED"},401);
  const origin=request.headers.get("Origin");if(origin!==url.origin||request.headers.get("Sec-Fetch-Site")==="cross-site")return authJson({error:"CROSS_SITE_REQUEST"},403);
  let body;try{body=await request.json()}catch{return authJson({error:"INVALID_JSON"},400)}
  if(body?.acceptNonRefundable!==true)return authJson({error:"REFUND_POLICY_REQUIRED"},400);
  const contactMethod=body.contactMethod==="whatsapp"?"whatsapp":body.contactMethod==="email"?"email":"";
  const contactValue=contactMethod==="whatsapp"?String(body.phone||"").trim().slice(0,32):String(user.email||"").trim();
  if(!contactMethod||!contactValue||(contactMethod==="whatsapp"&&!/^\+?[0-9\s()-]{8,20}$/.test(contactValue)))return authJson({error:"CONTACT_REQUIRED"},400);
  const c=await env.DB.prepare("SELECT status,entry_fee_jod,title FROM competitions WHERE id=?").bind(competitionId).first();
  if(!c||c.status!=="registration")return authJson({error:"REGISTRATION_CLOSED"},409);
  const existing=await env.DB.prepare("SELECT status FROM competition_requests WHERE competition_id=? AND user_id=?").bind(competitionId,user.id).first();
  if(existing)return authJson({error:"REQUEST_ALREADY_EXISTS",status:existing.status},409);
  const id=authUuid(),messageId=authUuid(),now=new Date().toISOString();
  await env.DB.batch([
   env.DB.prepare("INSERT INTO staff_messages (id,user_id,category,subject,body,contact_method,contact_value,competition_id,status,created_at,updated_at) VALUES (?,?, 'competition',?,?,?,?,?,'new',?,?)").bind(messageId,user.id,"طلب مشاركة في "+(c.title||"المسابقة"),String(body.message||"يرجى التواصل معي بخصوص المشاركة.").slice(0,2000),contactMethod,contactValue,competitionId,now,now),
   env.DB.prepare("INSERT INTO competition_requests (id,competition_id,user_id,status,fee_jod,note,created_at,updated_at,contact_method,contact_value,message_id) VALUES (?,?,?,'pending',?,'',?,?,?,?,?)").bind(id,competitionId,user.id,c.entry_fee_jod,now,now,contactMethod,contactValue,messageId)
  ]);
  return authJson({ok:true,requestId:id,messageId,message:"تم استلام طلبك. سيتواصل معك فريق LENSORA عبر الطريقة التي اخترتها لترتيب الدفع."},201);
 }
 if(path==="/api/competitions/admin/requests"&&request.method==="GET"){
  if(!await isStaff())return authJson({error:"STAFF_REQUIRED"},403);
  const rows=await env.DB.prepare("SELECT r.id,r.status,r.fee_jod,r.created_at,r.contact_method,r.contact_value,u.id AS user_id,u.username,u.first_name,u.last_name,u.email FROM competition_requests r JOIN users u ON u.id=r.user_id WHERE r.competition_id=? ORDER BY CASE r.status WHEN 'pending' THEN 0 ELSE 1 END,r.created_at").bind(competitionId).all();
  const c=await env.DB.prepare("SELECT COUNT(*) AS n FROM competition_participants WHERE competition_id=?").bind(competitionId).first();
  const comp=await env.DB.prepare("SELECT status FROM competitions WHERE id=?").bind(competitionId).first();
  return authJson({requests:rows.results||[],participantCount:Number(c?.n||0),capacity:64,competitionStatus:comp?.status||"draft"});
 }
 if(path==="/api/competitions/admin/activate"&&request.method==="POST"){
  if(!await isStaff())return authJson({error:"STAFF_REQUIRED"},403);
  const origin=request.headers.get("Origin");if(origin!==url.origin||request.headers.get("Sec-Fetch-Site")==="cross-site")return authJson({error:"CROSS_SITE_REQUEST"},403);
  let body;try{body=await request.json()}catch{return authJson({error:"INVALID_JSON"},400)}
  const requestId=String(body?.requestId||"");if(!/^[a-f0-9-]{36}$/i.test(requestId))return authJson({error:"INVALID_REQUEST_ID"},400);
  const req=await env.DB.prepare("SELECT id,user_id,status FROM competition_requests WHERE id=? AND competition_id=?").bind(requestId,competitionId).first();
  if(!req)return authJson({error:"REQUEST_NOT_FOUND"},404);
  if(req.status==="activated")return authJson({error:"ALREADY_ACTIVATED"},409);
  if(req.status!=="pending")return authJson({error:"REQUEST_NOT_PENDING"},409);
  const count=await env.DB.prepare("SELECT COUNT(*) AS n FROM competition_participants WHERE competition_id=?").bind(competitionId).first();
  if(Number(count?.n||0)>=64)return authJson({error:"COMPETITION_FULL"},409);
  const participantId=authUuid(),now=new Date().toISOString();
  const inserted=await env.DB.prepare("INSERT INTO competition_participants (id,competition_id,user_id,seed,joined_at) SELECT ?,?,?,(SELECT COUNT(*)+1 FROM competition_participants WHERE competition_id=?),? WHERE (SELECT COUNT(*) FROM competition_participants WHERE competition_id=?)<64 AND EXISTS(SELECT 1 FROM competition_requests WHERE id=? AND status='pending') AND NOT EXISTS(SELECT 1 FROM competition_participants WHERE competition_id=? AND user_id=?)").bind(participantId,competitionId,req.user_id,competitionId,now,competitionId,requestId,competitionId,req.user_id).run();
  if(!inserted.meta?.changes)return authJson({error:"CAPACITY_OR_STATUS_CHANGED"},409);
  await env.DB.prepare("UPDATE competition_requests SET status='activated',updated_at=? WHERE id=? AND status='pending'").bind(now,requestId).run();
  const joined=await env.DB.prepare("SELECT seed FROM competition_participants WHERE id=?").bind(participantId).first();
  return authJson({ok:true,participantId,seed:joined.seed,participantCount:joined.seed,message:"تم تفعيل المشاركة. أرسل تأكيداً للمشارك عبر البريد الإلكتروني."},200);
 }
 if(path==="/api/competitions/admin/launch"&&request.method==="POST"){
  if(!await isStaff())return authJson({error:"STAFF_REQUIRED"},403);
  const origin=request.headers.get("Origin");if(origin!==url.origin||request.headers.get("Sec-Fetch-Site")==="cross-site")return authJson({error:"CROSS_SITE_REQUEST"},403);
  const comp=await env.DB.prepare("SELECT status FROM competitions WHERE id=?").bind(competitionId).first();
  if(!comp)return authJson({error:"COMPETITION_NOT_FOUND"},404);
  if(comp.status!=="registration")return authJson({error:"NOT_READY_TO_LAUNCH"},409);
  await env.DB.prepare("UPDATE competitions SET status='active',updated_at=? WHERE id=? AND status='registration'").bind(new Date().toISOString(),competitionId).run();
  return authJson({ok:true,message:"تم إطلاق المسابقة وإظهار قائمة المشاركين للجميع."});
 }
 return authJson({error:"NOT_FOUND"},404);
}


async function handleStaff(request,env,url){
 if(!url.pathname.startsWith("/api/staff/"))return null;
 if(!env?.DB)return authJson({error:"DATABASE_UNAVAILABLE"},503);
 const user=await authCurrentUser(request,env);
 const member=user?await env.DB.prepare("SELECT role FROM staff_members WHERE user_id=?").bind(user.id).first():null;
 const staffOk=await panelSessionValid(request,env,"staff"),owner=member?.role==="owner"&&await panelSessionValid(request,env,"admin");
 if(staffOk){
  await env.DB.prepare("CREATE TABLE IF NOT EXISTS staff_user_features (user_id TEXT NOT NULL,feature_key TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL,updated_by TEXT NOT NULL,PRIMARY KEY(user_id,feature_key))").run();
  await env.DB.prepare("CREATE TABLE IF NOT EXISTS staff_user_actions (id TEXT PRIMARY KEY,staff_role TEXT NOT NULL,action TEXT NOT NULL,target_user_id TEXT NOT NULL,details TEXT,created_at TEXT NOT NULL)").run();
  await env.DB.prepare("CREATE TABLE IF NOT EXISTS profile_visits (profile_user_id TEXT NOT NULL,visitor_hash TEXT NOT NULL,visit_day TEXT NOT NULL,viewed_at TEXT NOT NULL,PRIMARY KEY(profile_user_id,visitor_hash,visit_day))").run();
 }
 if(url.pathname==="/api/staff/users"&&request.method==="GET"){
  if(!staffOk)return authJson({error:"STAFF_REQUIRED"},403);
  const q=String(url.searchParams.get("q")||"").trim().slice(0,80);if(q.length<2)return authJson({users:[]});
  const like="%"+q+"%";
  const rows=await env.DB.prepare("SELECT u.id,u.first_name,u.last_name,u.username,u.email,u.status,u.plan,u.created_at,(SELECT COUNT(*) FROM profile_visits v WHERE v.profile_user_id=u.id) AS visits FROM users u WHERE u.id=? OR u.username LIKE ? OR u.email LIKE ? OR u.first_name LIKE ? OR u.last_name LIKE ? ORDER BY u.created_at DESC LIMIT 30").bind(q,like,like,like,like).all();
  const features={};for(const id of (rows.results||[]).map(x=>x.id)){const f=await env.DB.prepare("SELECT feature_key,enabled FROM staff_user_features WHERE user_id=?").bind(id).all();features[id]=Object.fromEntries((f.results||[]).map(x=>[x.feature_key,!!x.enabled]));}
  return authJson({users:(rows.results||[]).map(x=>({...x,features:features[x.id]||{}}))});
 }
 if(url.pathname==="/api/staff/users/action"&&request.method==="POST"){
  if(!staffOk)return authJson({error:"STAFF_REQUIRED"},403);let b;try{b=await request.json()}catch{return authJson({error:"INVALID_JSON"},400)}
  const userId=String(b.userId||"").slice(0,80),action=String(b.action||"");const target=await env.DB.prepare("SELECT id,status FROM users WHERE id=?").bind(userId).first();if(!target)return authJson({error:"USER_NOT_FOUND"},404);
  const now=new Date().toISOString();let details="";
  if(action==="block"||action==="unblock"){if(action==="block"&&target.status!=="active")return authJson({error:"USER_NOT_ACTIVE"},409);if(action==="unblock"&&target.status!=="blocked")return authJson({error:"USER_NOT_BLOCKED"},409);await env.DB.prepare("UPDATE users SET status=?,updated_at=? WHERE id=?").bind(action==="block"?"blocked":"active",now,userId).run();details=String(b.reason||"").trim().slice(0,300);}
  else if(action==="feature"){const key=String(b.featureKey||"");const allowed=["profile_badge","rewards","portfolio_uploads","competitions","pro_tools"];if(!allowed.includes(key)||typeof b.enabled!=="boolean")return authJson({error:"INVALID_FEATURE"},400);await env.DB.prepare("INSERT INTO staff_user_features (user_id,feature_key,enabled,updated_at,updated_by) VALUES (?,?,?,?,?) ON CONFLICT(user_id,feature_key) DO UPDATE SET enabled=excluded.enabled,updated_at=excluded.updated_at,updated_by=excluded.updated_by").bind(userId,key,b.enabled?1:0,now,"staff-panel").run();details=key+":"+(b.enabled?"enabled":"disabled");}
  else return authJson({error:"INVALID_ACTION"},400);
  await env.DB.prepare("INSERT INTO staff_user_actions (id,staff_role,action,target_user_id,details,created_at) VALUES (?,?,?,?,?,?)").bind(authUuid(),"staff",action,userId,details,now).run();return authJson({ok:true});
 }
 if(url.pathname==="/api/staff/users/audit"&&request.method==="GET"){if(!staffOk)return authJson({error:"STAFF_REQUIRED"},403);const rows=await env.DB.prepare("SELECT a.action,a.target_user_id,a.details,a.created_at,u.username,u.first_name,u.last_name FROM staff_user_actions a LEFT JOIN users u ON u.id=a.target_user_id ORDER BY a.created_at DESC LIMIT 100").all();return authJson({actions:rows.results||[]});}
 if(request.method==="POST"){const origin=request.headers.get("Origin");if(origin!==url.origin||request.headers.get("Sec-Fetch-Site")==="cross-site")return authJson({error:"CROSS_SITE_REQUEST"},403)}
 if(url.pathname==="/api/staff/messages"&&request.method==="POST"){
  if(!user)return authJson({error:"AUTH_REQUIRED"},401);
  let b;try{b=await request.json()}catch{return authJson({error:"INVALID_JSON"},400)}
  const category=["complaint","suggestion","competition"].includes(b.category)?b.category:"";
  const body=String(b.body||"").trim().slice(0,3000),method=b.contactMethod==="whatsapp"?"whatsapp":b.contactMethod==="email"?"email":"";
  const contact=method==="whatsapp"?String(b.phone||"").trim().slice(0,32):String(user.email||"");
  if(!category||body.length<3||!method||!contact||(method==="whatsapp"&&!/^\+?[0-9\s()-]{8,20}$/.test(contact)))return authJson({error:"INVALID_MESSAGE"},400);
  const id=authUuid(),now=new Date().toISOString();
  await env.DB.prepare("INSERT INTO staff_messages (id,user_id,category,subject,body,contact_method,contact_value,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,'new',?,?)").bind(id,user.id,category,category==="complaint"?"شكوى":category==="suggestion"?"اقتراح":"استفسار عن المسابقات",body,method,contact,now,now).run();
  return authJson({ok:true,id,message:"تم إرسال رسالتك إلى فريق الموظفين."},201);
 }
 if(url.pathname==="/api/staff/messages"&&request.method==="GET"){
  if(!staffOk)return authJson({error:"STAFF_REQUIRED"},403);
  const rows=await env.DB.prepare("SELECT m.id,m.category,m.subject,m.body,m.contact_method,m.contact_value,m.competition_id,m.status,m.staff_note,m.created_at,u.username,u.first_name,u.last_name,u.email FROM staff_messages m JOIN users u ON u.id=m.user_id ORDER BY CASE m.status WHEN 'new' THEN 0 WHEN 'contacted' THEN 1 ELSE 2 END,m.created_at DESC LIMIT 250").all();
  return authJson({messages:rows.results||[],role:"staff"});
 }
 if(url.pathname==="/api/staff/messages/status"&&request.method==="POST"){
  if(!staffOk)return authJson({error:"STAFF_REQUIRED"},403);
  let b;try{b=await request.json()}catch{return authJson({error:"INVALID_JSON"},400)}
  const status=["new","contacted","resolved"].includes(b.status)?b.status:"";
  if(!status||!b.messageId)return authJson({error:"INVALID_INPUT"},400);
  await env.DB.prepare("UPDATE staff_messages SET status=?,updated_at=? WHERE id=?").bind(status,new Date().toISOString(),String(b.messageId)).run();
  return authJson({ok:true});
 }
 if(url.pathname==="/api/staff/members"&&request.method==="POST"){
  if(!owner)return authJson({error:"OWNER_REQUIRED"},403);
  let b;try{b=await request.json()}catch{return authJson({error:"INVALID_JSON"},400)}
  const email=String(b.email||"").trim().toLowerCase();
  const target=await env.DB.prepare("SELECT id FROM users WHERE email_norm=? AND status='active'").bind(email).first();
  if(!target)return authJson({error:"USER_NOT_FOUND"},404);
  await env.DB.prepare("INSERT OR REPLACE INTO staff_members (user_id,role,created_at) VALUES (?,'staff',?)").bind(target.id,new Date().toISOString()).run();
  return authJson({ok:true});
 }
 return authJson({error:"NOT_FOUND"},404);
}

export default {async fetch(request,env){const url=new URL(request.url);let pathname=url.pathname;try{pathname=decodeURIComponent(pathname)}catch(e){return new Response("Invalid URL",{status:400})}if(pathname.startsWith("/media/")){try{const response=await handleMedia(request,env,url);if(response)return response}catch(e){console.error("LENSORA_MEDIA_ERROR",e);return new Response("Media error",{status:500})}}if(pathname.startsWith("/api/portfolio/works")){try{const response=await handlePortfolio(request,env,url);if(response)return response}catch(e){const requestId=crypto.randomUUID();console.error("LENSORA_PORTFOLIO_ERROR",requestId,e);return authJson({error:"SERVER_ERROR",requestId},500)}}if(pathname.startsWith("/api/panel-auth/")){try{const response=await handlePanelAuth(request,env,url);if(response)return response}catch(e){const requestId=crypto.randomUUID();console.error("LENSORA_PANEL_AUTH_ERROR",requestId,e);return authJson({error:"SERVER_ERROR",requestId},500)}}if(pathname.startsWith("/api/admin/")){try{const response=await handleAdmin(request,env,url);if(response)return response}catch(e){const requestId=crypto.randomUUID();console.error("LENSORA_ADMIN_ERROR",requestId,e);return authJson({error:"SERVER_ERROR",requestId},500)}}if(pathname.startsWith("/api/staff/")){try{const response=await handleStaff(request,env,url);if(response)return response}catch(e){const requestId=crypto.randomUUID();console.error("LENSORA_STAFF_ERROR",requestId,e);return authJson({error:"SERVER_ERROR",requestId},500)}}if(pathname.startsWith("/api/competitions")){try{const response=await handleCompetitions(request,env,url);if(response)return response}catch(e){const requestId=crypto.randomUUID();console.error("LENSORA_COMPETITIONS_ERROR",requestId,e);return authJson({error:"SERVER_ERROR",requestId},500)}}if(pathname.startsWith("/api/auth/")){try{const response=await handleAuth(request,env,url);if(response)return response}catch(e){const requestId=crypto.randomUUID();console.error("LENSORA_AUTH_ERROR",requestId,e);return authJson({error:"SERVER_ERROR",requestId},500)}}if(pathname==="/api/profile-services"){try{const response=await handleCreatorServices(request,env,url);if(response)return response}catch(e){const requestId=crypto.randomUUID();console.error("LENSORA_SERVICES_ERROR",requestId,e);return authJson({error:"SERVER_ERROR",requestId},500)}}if(pathname.startsWith("/api/profile/")){try{const response=await handleProfile(request,env,url);if(response)return response}catch(e){const requestId=crypto.randomUUID();console.error("LENSORA_PROFILE_ERROR",requestId,e);return authJson({error:"SERVER_ERROR",requestId},500)}}if(pathname==="/health")return new Response("LENSORA OK",{headers:{"content-type":"text/plain; charset=utf-8","cache-control":"no-store"}});if(pathname!=="/"&&pathname!=="/index.html"&&pathname!=="/competitions"&&pathname!=="/competitions/demo"&&pathname!=="/staff"&&pathname!=="/admin"&&!(pathname.startsWith("/@")&&pathname.slice(2).split("").every(c=>"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-".includes(c))))return new Response("Not found",{status:404});return new Response(PAGE,{headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff","referrer-policy":"strict-origin-when-cross-origin","x-frame-options":"DENY","content-security-policy":"default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; img-src 'self' data: https:; font-src 'self' https://fonts.gstatic.com; connect-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'","permissions-policy":"camera=(), microphone=(), geolocation=()"}})}};
